<script setup>
/**
 * CourseCard.vue - 课程卡片
 * 
 * 展示内容:
 * - 课程封面
 * - 课程标题
 * - 讲师名称
 * - 课程时长
 * - 学员数量
 * - 评分星级
 * - 价格 (0表示免费)
 * 
 * Props:
 * - course: object - 课程数据对象
 *   { id, title, instructor, cover, duration, students, rating, price, category }
 */

defineProps({
  course: {
    type: Object,
    required: true
  }
})

// 生成星级评分显示
const getStarRating = (rating) => {
  const full = Math.floor(rating || 0)
  const half = (rating || 0) - full >= 0.5 ? 1 : 0
  return { full, half, empty: 5 - full - half }
}
</script>

<template>
  <div class="course-card" v-if="course">
    <!-- 封面区域 -->
    <div class="cover-wrapper">
      <img
        :src="course.cover || '/images/course-placeholder.jpg'"
        :alt="course.title"
        class="cover-image"
        loading="lazy"
      />
      <!-- 时长标签 -->
      <span class="duration-badge" v-if="course.duration">
        {{ course.duration }}
      </span>
      <!-- 价格标签 -->
      <span class="price-badge" :class="{ free: course.price === 0 }">
        {{ course.price === 0 ? '免费' : '¥' + course.price }}
      </span>
      <!-- 悬停遮罩 -->
      <div class="cover-overlay">
        <span class="play-icon">▶</span>
      </div>
    </div>

    <!-- 内容区域 -->
    <div class="card-body">
      <h3 class="course-title">{{ course.title }}</h3>
      <p class="course-instructor">{{ course.instructor }}</p>

      <!-- 统计信息 -->
      <div class="course-stats">
        <span class="stat-item">
          👥 {{ course.students || 0 }} 学员
        </span>
      </div>

      <!-- 评分 -->
      <div class="course-rating" v-if="course.rating">
        <span class="stars">
          <span
            v-for="n in getStarRating(course.rating).full"
            :key="'f' + n"
            class="star filled"
          >★</span>
          <span
            v-for="n in getStarRating(course.rating).half"
            :key="'h' + n"
            class="star half"
          >★</span>
          <span
            v-for="n in getStarRating(course.rating).empty"
            :key="'e' + n"
            class="star empty"
          >★</span>
        </span>
        <span class="rating-value">{{ course.rating.toFixed(1) }}</span>
      </div>
    </div>
  </div>
</template>

